-- Refunds: let orders.payment_status record that a card payment was
-- (fully or partly) refunded. The original check from 0001 only allowed
-- pending / paid / failed / cod_pending.
--
-- The constraint is dropped by looking it up rather than by name, since the
-- name was auto-generated by Postgres.

do $$
declare
  c text;
begin
  select conname into c
  from pg_constraint
  where conrelid = 'public.orders'::regclass
    and contype = 'c'
    and pg_get_constraintdef(oid) ilike '%payment_status%';

  if c is not null then
    execute format('alter table public.orders drop constraint %I', c);
  end if;
end $$;

alter table public.orders
  add constraint orders_payment_status_check
  check (payment_status in ('pending', 'paid', 'failed', 'cod_pending', 'refunded', 'partially_refunded'));
